export IMPLEMENT_TMPDIR=<TMPDIR>
cat "$IMPLEMENT_TMPDIR/accumulated-oos.jsonl" 2>/dev/null | python3 -c "
import sys, json
for i, line in enumerate(sys.stdin):
    try:
        d = json.loads(line.strip())
        print(f'Item {i}: accepted={d.get(\"accepted\")}, finding_id={d.get(\"finding_id\")}, result={d.get(\"result\")}, title={str(d.get(\"title\",\"\"))[:60]}')
    except Exception as e:
        print(f'ERROR {i}: {e}')
" 2>/dev/null
